import { CipherLink, type CipherLinkProps } from "../lib/link";
import { useStretchedLink } from "../lib/stretched-link";
import { cn } from "../lib/utils";
import { Icon } from "./icon";

import styles from "./row-link.module.css";

function RowLink({
  className,
  disabled,
  chevron = true,
  title,
  children,
  ref,
  ...props
}: CipherLinkProps & {
  disabled?: boolean;
  chevron?: boolean;
}) {
  const off = disabled ?? (props.link as { disabled?: boolean }).disabled;
  useStretchedLink(!off);
  const content = chevron ? (
    <>
      <span className={styles.label}>{children}</span>
      <Icon name="chev-right" className={styles.chevron} data-row-link-chevron="" />
    </>
  ) : (
    children
  );
  if (off)
    return (
      <span
        role="link"
        aria-disabled="true"
        title={title}
        data-slot="row-link"
        data-disabled=""
        data-chevron={chevron || undefined}
        className={cn(styles.rowLink, className)}
      >
        {content}
      </span>
    );
  return (
    <CipherLink
      ref={ref}
      title={title}
      data-slot="row-link"
      data-row-link=""
      data-chevron={chevron || undefined}
      className={cn(styles.rowLink, styles.stretched, className)}
      {...props}
    >
      {content}
    </CipherLink>
  );
}

export { RowLink };

.rowLink {
  display: block;
  min-width: 0;
  overflow: hidden;
  color: inherit;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
  outline: none;
}
.rowLink[data-disabled] {
  color: var(--v4-muted);
  cursor: not-allowed;
}
.rowLink[data-chevron] {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: var(--v4-space-8);
}
.label {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chevron {
  flex: none;
  width: var(--v4-size-glyph);
  height: var(--v4-size-glyph);
  stroke-width: var(--v4-stroke-icon);
  color: var(--v4-muted);
  transition: color var(--v4-duration-fast) var(--v4-ease-fade);
}
.rowLink[data-disabled] .chevron {
  color: var(--v4-faint);
}
:is(:global(tr), :global([data-slot="card"])):is(:hover, :focus-within) .stretched .chevron {
  color: var(--v4-ink);
}
.cardLink {
  color: inherit;
  text-decoration: none;
  outline: none;
}
.cardLink[data-disabled] {
  color: var(--v4-muted);
  cursor: not-allowed;
}
.stretched::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
}
.stretched:focus-visible::after {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: calc(-1 * var(--v4-size-focus-ring));
}
:global(tr)[data-stretched-link],
:global([data-slot="card"])[data-stretched-link] {
  position: relative;
  cursor: pointer;
}
:global([data-slot="card"])[data-stretched-link]:hover {
  background-image: linear-gradient(var(--v4-action-ghost-hover), var(--v4-action-ghost-hover));
}
/* :where keeps this at zero specificity, so a control that positions itself absolutely keeps its own layout. */
:where(:global(tr)[data-stretched-link], :global([data-slot="card"])[data-stretched-link])
  :where(
    button,
    input,
    select,
    textarea,
    label,
    summary,
    a:not(.stretched),
    [role="button"],
    [role="checkbox"],
    [role="combobox"],
    [role="switch"],
    [data-slot="tooltip-trigger"],
    [data-row-interactive]
  ) {
  position: relative;
  z-index: 2;
}
